WITH gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) + INTERVAL '30' DAY THEN 1 ELSE 0 END AS session_start_flag FROM payments), sessionized AS (SELECT id, order_id, amount, paid_at, status, SUM(session_start_flag) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT DATE_TRUNC('YEAR', paid_at) AS year_start, DATE_TRUNC('MONTH', paid_at) AS activity_month, SUM(CASE WHEN status = 'SUCCESS' THEN amount ELSE 0 END) AS success_amount, COUNT(*) FILTER (WHERE status = 'FAILED') AS failed_rows, APPROX_PERCENTILE(session_no, 0.9) AS session_no_p90, COUNT(CASE WHEN status = 'FAILED' THEN 1 END) AS failed_count, MIN(paid_at) AS first_paid_at, RANK() OVER (PARTITION BY DATE_TRUNC('YEAR', paid_at) ORDER BY APPROX_PERCENTILE(session_no, 0.9) DESC) AS session_no_p90_rank FROM sessionized GROUP BY DATE_TRUNC('YEAR', paid_at), DATE_TRUNC('MONTH', paid_at);
